    void worker_loop() {
        uint64_t seen = 0;
        for (;;) {
            ExpertDoorbell* d = nullptr;
            int m = 1;
            bool dspark_job = false;
            {
                std::unique_lock<std::mutex> lk(mu);
                cv.wait(lk, [&] { return stop.load() || go != seen; });
                if (stop) return;
                seen = go;
                d = job_db;
                m = job_m;
                dspark_job = job_dspark;
            }
            if (dspark_job) run_dspark_job(d, m);
            else run_job(d, m);
